fn dangle() -> &String {   // error[E0106]: missing lifetime specifier
    let s = String::from("hello");
    &s
} // s is dropped here — the reference above would point at freed memory

fn main() {
    let mut s = String::from("hello");

    let r1 = &s;
    let r2 = &s;
    println!("{} and {}", r1, r2);   // r1, r2's last use — their borrow ends here (NLL)

    let r3 = &mut s;                  // fine: no shared borrow is still active
    r3.push_str(", world");
    println!("{}", r3);
}

fn longest(x: &str, y: &str) -> &str {   // error[E0106]: missing lifetime specifier
    if x.len() > y.len() { x } else { y }
}

fn longest<'a>(x: &'a str, y: &'a str) -> &'a str {
    if x.len() > y.len() { x } else { y }
}

fn main() {
    let s1 = String::from("long string is long");
    let result;
    {
        let s2 = String::from("short");
        result = longest(s1.as_str(), s2.as_str());
        println!("longest: {}", result); // fine — s2 is still alive here
    }
    // println!("{}", result); // would be a compile error: s2 (and its borrow) is gone
}

