fn first_word(s: &str) -> &str {
    match s.find(' ') {
        Some(i) => &s[..i],
        None => s,
    }
} // no 'a written anywhere — elision rule 2 assigns the single input's
  // lifetime to the elided output automatically

use std::cell::Cell;

let hits = Cell::new(0);
let r1 = &hits;
let r2 = &hits;      // any number of shared references is fine
r1.set(r1.get() + 1); // mutate THROUGH a shared reference
r2.set(r2.get() + 1);
println!("{}", hits.get()); // 2

use std::cell::RefCell;

let log = RefCell::new(Vec::new());
log.borrow_mut().push("first");      // exclusive borrow, used, then dropped
{
    let a = log.borrow();             // shared borrow
    let b = log.borrow();             // fine: multiple shared borrows allowed
    println!("{} entries", a.len() + b.len() - a.len());
} // a, b dropped here
log.borrow_mut().push("second");     // fine: no outstanding borrows now

use std::sync::{Arc, Mutex};
use std::thread;

let counter = Arc::new(Mutex::new(0));
let mut handles = vec![];
for _ in 0..4 {
    let counter = Arc::clone(&counter);
    handles.push(thread::spawn(move || {
        let mut n = counter.lock().unwrap(); // blocks until the lock is free
        *n += 1;
    })); // guard dropped here -> lock released
}
for h in handles { h.join().unwrap(); }
println!("{}", *counter.lock().unwrap()); // 4

