let config_max: Option<u8> = Some(3);

// Full match — handles every case:
match config_max {
    Some(max) => println!("max is {max}"),
    None => (),
}

// Same logic with if let — but the None case is now silently skipped
// unless you add an else:
if let Some(max) = config_max {
    println!("max is {max}");
} else {
    println!("no max was set");
}

